═ // propiedades de auditoría // ═══════════════════════════════════════════════════════════════════ builder.property(e = e.createdat) .isrequired(); builder.property(e = e.createdby) .hasmaxlength( 256 ); builder.property(e = e.modifiedat); builder.property(e = e.modifiedby) .hasmaxlength( 256 ); // ═══════════════════════════════════════════════════════════════════ // soft delete // ═══════════════════════════════════════════════════════════════════ builder.property(e = e.isdeleted) .hasdefaultvalue( false ); builder.property(e = e.deletedat); builder.property(e = e.deletedby) .hasmaxlength( 256 ); // query filter para soft delete builder.hasqueryfilter(e = !e.isdeleted); // ═══════════════════════════════════════════════════════════════════ // índices // ═══════════════════════════════════════════════════════════════════ {{configuracionindices}} // ═══════════════════════════════════════════════════════════════════ // relaciones // ═══════════════════════════════════════════════════════════════════ {{configuracionrelaciones}} } } // ═══════════════════════════════════════════════════════════════════════════ // patrones de configuración comunes // ═══════════════════════════════════════════════════════════════════════════ /* // strings builder.property(e = e.name) .isrequired() .hasmaxlength( 200 ); builder.property(e = e.description) .hasmaxlength( 2000 ); builder.property(e = e.code) .isrequired() .hasmaxlength( 20 ) .isunicode( false ); // varchar en lugar de nvarchar // decimales builder.property(e = e.amount) .hasprecision( 18 , 2 ); // decimal( 18 , 2 ) builder.property(e = e.porcentaje) .hasprecision( 5 , 2 ); // decimal( 5 , 2 ) // fechas builder.property(e = e.createdat) .hascolumntype( datetime2(3) ); // precisión de milisegundos builder.property(e = e.solofecha) .hascolumntype( date ); // enums builder.property(e = e.status) .hasconversion string () // guardar como string .hasmaxlength( 50 ); builder.property(e = e.tipo) .hasconversion int (); // guardar como int (default) // value objects (complex types .net 10 ) builder.complexproperty(e = e.period, p = { p.property(x = x.startdate).hascolumnname( startdate ); p.property(x = x.enddate).hascolumnname( enddate ); }); // o como owned type (versiones anteriores) builder.ownsone(e = e.address, d = { d.property(x = x.calle).hascolumnname( address_calle ).hasmaxlength( 200 ); d.property(x = x.city).hascolumnname( address_city ).hasmaxlength( 100 ); d.property(x = x.codepostal).hascolumnname( address_cp ).hasmaxlength( 10 ); }); // índices builder.hasindex(e = e.code) .isunique() .hasdatabasename( ix_{{entities}}_code ); builder.hasindex(e = e.status) .hasdatabasename( ix_{{entities}}_estado ); builder.hasindex(e = new { e.status, e.createdat }) .hasdatabasename( ix_{{entities}}_estado_fecha ); // índice filtrado (solo activos) builder.hasindex(e = e.email) .isunique() .hasfilter( [isdeleted] = 0 ) .hasdatabasename( ix_{{entities}}_email ); // relaciones - uno a muchos builder.hasmany(e = e.applications) .withone(s = s.scholarship) .hasforeignkey(s = s.scholarshipid) .ondelete(deletebehavior.restrict); // no cascade // relaciones - muchos a uno builder.hasone(e = e.category) .withmany(c = c.{{entities}}) .hasforeignkey(e = e.categoryid) .ondelete(deletebehavior.restrict); // relaciones - muchos a muchos (ef core 5 +) builder.hasmany(e = e.tags) .withmany(t = t.{{entities}}) .usingentity dictionary string, object ( {{entity}}tag , j = j.hasone tag ().withmany().hasforeignkey( tagid ), j = j.hasone {{entity}} ().withmany().hasforeignkey( {{entity}}id )); // conversiones personalizadas builder.property(e = e.metadata) .hasconversion( v = jsonserializer.serialize(v, (jsonserializeroptions) null !), v = jsonserializer.deserialize dictionary string, string (v, (jsonserializeroptions) null !)! ); // json column (.net 10 / sql server 2022 ) builder.ownsone(e = e.configuracion, c = { c.tojson(); }); */ // ==========================================================================