mmary /// obtiene listado paginado de {{entities}} /// /summary /// param name= page número de página ( 1 -based) /param /// param name= size elementos por página /param /// param name= ct token de cancelación /param [httpget] [producesresponsetype paginatedresult {{entity}}dto (statuscodes.status200ok)] public async task actionresult paginatedresult {{entity}}dto getall( [fromquery] int page = 1 , [fromquery] int size = 10 , cancellationtoken ct = default) { var result = await _mediator.send(new get{{entities}}query(page, size), ct); return ok(result); } /// summary /// obtiene un/a {{entity}} por su id /// /summary [httpget( {id:int} )] [producesresponsetype {{entity}}dto (statuscodes.status200ok)] [producesresponsetype(statuscodes.status404notfound)] public async task actionresult {{entity}}dto getbyid( int id, cancellationtoken ct = default) { var result = await _mediator.send(new get{{entity}}byidquery(id), ct); if (result is null ) { return notfound(new problemdetails { title = {{entity}} not found , detail = $ no {{entity}} with id {id} , status = statuscodes.status404notfound }); } return ok(result); } // ═══════════════════════════════════════════════════════════════════════ // post - crear // ═══════════════════════════════════════════════════════════════════════ /// summary /// crea un/a nuevo/a {{entity}} /// /summary [httppost] [authorize(roles = admin,manager )] [producesresponsetype {{entity}}dto (statuscodes.status201created)] [producesresponsetype validationproblemdetails (statuscodes.status400badrequest)] public async task actionresult {{entity}}dto create( [frombody] create{{entity}}command request, cancellationtoken ct = default) { var result = await _mediator.send(request, ct); _logger.loginformation( {{entity}} {id} created by {user} , result.id, user.identity?.name); return createdataction(nameof(getbyid), new { id = result.id }, result); } // ═══════════════════════════════════════════════════════════════════════ // put - actualizar // ═══════════════════════════════════════════════════════════════════════ /// summary /// actualiza un/a {{entity}} existente /// /summary [httpput( {id:int} )] [authorize(roles = admin,manager )] [producesresponsetype(statuscodes.status204nocontent)] [producesresponsetype(statuscodes.status404notfound)] [producesresponsetype validationproblemdetails (statuscodes.status400badrequest)] public async task iactionresult update( int id, [frombody] update{{entity}}command request, cancellationtoken ct = default) { if (id != request.id) { return badrequest(new problemdetails { title = id mismatch , detail = the id in the route does not match the id in the body , status = statuscodes.status400badrequest }); } await _mediator.send(request, ct); _logger.loginformation( {{entity}} {id} updated by {user} , id, user.identity?.name); return nocontent(); } // ═══════════════════════════════════════════════════════════════════════ // delete - eliminar (borrado logico) // ═══════════════════════════════════════════════════════════════════════ /// summary /// elimina un/a {{entity}} (soft delete) /// /summary [httpdelete( {id:int} )] [authorize(roles = admin )] [producesresponsetype(statuscodes.status204nocontent)] [producesresponsetype(statuscodes.status404notfound)] public async task iactionresult delete( int id, cancellationtoken ct = default) { await _mediator.send(new delete{{entity}}command(id), ct); _logger.loginformation( {{entity}} {id} deleted by {user} , id, user.identity?.name); return nocontent(); } } // ═══════════════════════════════════════════════════════════════════════════ // registro del versionado (en program.cs, una vez por aplicacion) // ═══════════════════════════════════════════════════════════════════════════ // el generador emite rutas versionadas porque la regla `api` y el agent api-contract-validator las // exigen: sin esto, cada crud nacia incumpliendo la convencion que el propio auditor del ecosistema // le iba a senalar (adr-027). notfoundexception y domainexc